    passage:
      '「大器晩成」という言葉は、昔ほどその意味を素直に受け取れなくなっている。年功序列が揺らぎ、社会の変化が速くなった今、晩く花開く人を待つ社会の余裕そのものが減っているからだ。若いうちに結果を出せ、という圧力は、学校から職場まで一貫して強まっている。\nしかし、急いで出した結果には、視野の狭さがつきまとう。早くから一つの分野で頭角を現した人は、その分野の枠内で考える癖がつきやすい。一方、あちこちの分野を回り道してきた人は、分野をつなぐ視点を持ちやすい。回り道は時間の無駄のようにみえて、後になって独自の力になる。⟪晩成とは、単に完成が遅いことではなく、完成までに多くの材料を集めてきたということなのだ⟫。\nもちろん、すべての回り道が実るわけではない。若いうちに結果を出すことが悪いわけでもない。問題は、速さだけを測る物差しで人を評価するとき、待つ側に回る人の経験が「遅れ」という一点で片付けられてしまうことである。集めた材料の種類も量も見られないまま、歩んだ道の長さだけが問われる。それで失われるものが何かを、評価する側はもう少し考えてもよいのではないか。',
