      '壊れた家電を、今の人はどうするだろうか。買い替える、が八割方の答えだろう。修理に要する時間と費用が、新品の価格に迫るからだ。この計算は正しい。正しいのだが、その計算表そのものが、過去半世紀で書き換えられた。かつて家電は、修理を前提に設計されていた。分解すれば直る構造、部品の長期保証。メーカーは修理のネットワークを財産として抱え、壊れないものを作るより、直り続けるものを作ることで信頼を売った。\n変わったのは、二つの事情だ。一つは製品の精密化である。薄型化と一体型は、分解を前提としない構造になった。もう一つは、価格の下落だ。量産と海外生産で、新品は修理の費用帯へ落ちてきた。修理を割に合わなくしたのは、職人の腕の低下でも、消費者の見栄でもなく、この二つの重なりである。\nだとすれば、修理の衰退は止められないのかというと、ここ十年で逆方向の流れも育ち始めた。修理できる権利を製品に保障せよという立法の動き。部品の長期供給を約款に書くメーカー。分解手順を公開する動画。直るものを捨てることへの、静かな気まずさ。\n⟪修理の復活は、懐の深さの問題ではなく、物と向き合う時間を誰が持つかという、生活設計の問題である⟫。買うときの値段だけが物との契約ではない。十年のあいだ誰が直し、いつ手放すかまで含めて、モノの値段は支払われる。修理という選択肢が消えた社会は、物の一生を工場とゴミ袋の間の一方通行にする。直すという行為は、物の寿命を延ばすと同時に、所有者のほうの、物を見る眼を数年分、延ばしてくれる。',
