      '家の間取りは、家族の形を写す鏡である。戦後の日本の家は、お茶の間を中心に回っていた。六畳の和室にテレビがあり、家族は同じ時間に同じ番組を見た。個室は夜眠るための場所で、生活の中心ではなかった。団地の時代には、「nLDK」という表記が生まれた。リビングとダイニングが一つになり、個室の数が家の価値を表す単位になった。家族は集まる場所と、個々に引こもる場所を、別々に持つようになった。個室化は、プライバシーの発明だった。一人の時間を持てない家族の中で、自分の部屋は自分の国になる。子どもは自分の部屋で、親からは見えない時間を持つことを学んだ。\nところが近年、間取りの流行がまた変わった。個室を減らし、家族の共有空間を広げる家が増えた。理由の一つは、子どもが自分の部屋にこもり、家族の会話が消えたことへの不安である。もう一つは、リモートワークの普及だ。仕事が家に入ってくると、部屋の数では足りなくなる。夫婦が別々の部屋で別々の会議をする生活は、個室の再発明でもある。間取りは、家族が「一緒にいること」と「別々にいること」をどう両立させるかという問いに対する、時代ごとの答えの集積である。\n間取りの変遷を見ていると、建築の流行が家族の理想の変化を先取りしていることに気づく。お茶の間の時代は、家族の団らんが理想だった。個室の時代は、プライバシーが理想だった。今の時代の理想は何か。建築家の言葉を借りれば、「一緒にいられる場所と、一人になれる場所を、家の中で行き来できること」だ。家の中に距離を作るのではなく、距離を行き来する動線を作る。⟪間取りは、家族の距離の設計図なのである⟫。',
