    passage:
      'スマートフォンのアプリを入れるとき、「利用規約に同意する」のボタンを押す。規約を全部読んだ人は、ほとんどいない。長さは数十頁、文言は法律の専門家でも読み飽きる。それでも人は押す。押さないと道具が使えないからだ。同意のボタンは、形の上では大切な判断の瞬間である。契約に署名するのと同じ重みを持つはずの行為だ。現実には、読まれないことを前提にした、最も軽いクリックになってしまっている。\nこの空洞化は、事業者だけの責任ではない。利用者にも、読まない理由がある。規約は長く、専門的で、項目ごとに重要度が違う。すべてを同じ形式で並べられたなら、読む前に力尽きる。情報の量が読む量を超えたとき、人は全部を読まないか、全部を読んだことにするか、どちらかを選ぶ。どちらも選ばないという選択肢はない。\n⟪同意とは、読ませることではなく、読まれるべき箇所を守ることだ⟫。同意の設計が問われるべきは、書き手の都合のよさではなく、読み手の注意力の有限さである。契約の中身の中で、本当に人が判断すべきものは何か。支払いの条件か、データの取り扱いか、解約の規定か。重要な少数を、読む負担の少ない形で分離して示す。そのうえで残りを要約する。読ませる努力は、量の削減ではなく、重みの順番の設計として行われるべきだ。\nもちろん、設計だけでは限界がある。読まれるべき箇所を事業者が自分で選ぶなら、都合の悪い条項が「重要」から外される恐れがある。だからこそ、同意の設計には、事業者以外の視点——消費者団体のレビュー、第三者の検証——が要る。同意の空洞化を埋める作業は、一人の注意の問題ではなく、仕組みの問題なのである。',
