    passage:
      '交渉の達人は、譲らない人だと思われている。実際は逆で、達人は譲るのがうまい。ただし、譲り方に設計がある。達人の譲歩には、三つの特徴がある。一つ、先に譲らない。一つ、段階を追って小さく譲る。一つ、譲ったものに名前をつける。「今回は、納期を一週間譲ります」。譲歩に名前をつけると、譲ったものが、ただの提供ではなく、相手への与件として記録される。\n素人が交渉で失敗するのは、譲れないものを最初に全部出すからだ。誠意を見せようとして、手持ちの譲歩を一度に並べる。相手は、それが譲歩だったと認識しない。最初から出された条件は、ただの条件である。譲歩とは、前の条件からの差分であって、初回提示の条件には差分がない。つまり、譲ることの価値は、譲る順番と幅の設計から生まれる。\nそして、譲歩には「交換」を添える。一方的な譲歩は、弱さの表明と受け取られる。納期を譲るなら、何かをもらう。「納期は一週間延ばします。その代わり、検収の基準を事前に確定させてください」。譲歩と取得を一組にすると、譲歩は損失ではなく、取引の一部になる。交渉が終わった後の関係まで考えるなら、達人の譲歩は、相手に勝ちを感じさせる設計になっている。譲った本人が譲ったことを覚えていても、相手が「勝った」と感じている交渉は、次の取引を呼ぶ。',
