    passage:
      '孤独な仕事がある。一人で進め、進捗が外から見えない仕事。研究、執筆、遠隔地の業務。孤独な仕事の困難は、孤独そのものではなく、報告の相手がいないことである。進んでいるのか、止まっているのか、困っているのか。外からは分からない。本人が報告しないかぎり、外の世界の時間は、静止している。孤独な仕事の遅れは、報告がないことで、初めて発覚する。発覚したときには、手遅れのことが多い。\n孤独な仕事をする人に、進捗の報告を勧める人がいる。勧められる本人は、報告する材料がないと答える。仕事は、まだ終わっていない。終わっていない仕事は、報告の材料にならない、という思い込みである。進捗の報告は、完成の報告ではない。困っていること、止まっていること、試して駄目だったこと。これらは、すべて報告の材料である。むしろ、完成まで報告のない仕事は、報告の機会を、一番困っているときまで延ばしていたことになる。\nだから私は、孤独な仕事には「困りごとの報告」を設計することを勧める。週に一度、進んだことではなく、困ったことを報告する。困りの報告は、助けの依頼ではない。外の時間を、仕事の中の時間と合わせるための、情報の合図である。困りの報告を受けた側は、助けを差し出す前に、まず仕事の現在地を知る。孤独な仕事の孤独は、仕事の内容から来るのではない。報告の設計がないことから来る。報告の設計があれば、孤独な仕事は、孤独でなくなる。',
