      '同じレシピを追っても、昨日の味が明日も出るとは限らない。料理の失敗を丁寧に検証すると、手順の誤りより先に、条件の差が浮かぶことが多い。同じ三十秒でも、夏の台所と冬の台所では生地の温度が違う。同じ小麦粉でも、袋の残り具合で吸った湿気が違う。寝かせる時間の長さで、麺の伸びも変わる。フライパンの厚みが変われば火の入り方は変わるし、コンロの出力の目盛りはメーカーごとにまちまちだ。初心者は失敗の原因を自分の腕に求めがちだが、多くの場合、原因は腕ではなく環境の変数に潜んでいる。⟪レシピとは、無数の条件をある一つの組み合わせに固定した、一時的な解の記録にすぎない。⟫だから上達とは、手順を暗記することではなく、条件の変化を読み取る目を養うことである。生地の表面を見て水分を足すか判断する、油の音で揚げ加減を聞き分ける。レシピの数字は目安であり、最後の一手は目と耳に委ねられる。そうした感知と調整の反復が、少しずつ体に覚えられていく。失敗した翌日には、まず温度計を片手に、昨日との違いを数えてみるとよい。腕前とは、条件の差を数えることから始まる。',
