      '傘を借りた翌朝、玄関先で乾いた傘を差し出す。この動作に迷いは少ないはずだ。だが、一晩後にするか、三日後にするか、次の雨の日にするかで、受け取る側の味わいは微妙に変わる。返すタイミングは、返すという行為そのものと同じだけ神経が使われる領域である。\n翌朝の返却は、物が役目を終えてすぐ手元へ戻る、きれいな形だ。ただし、あまりに即時の返却は、借りたことへの負い目を早く解消したいという含意に読まれる場合がある。逆に、間隔を空けすぎた返却は、物の記憶が薄れてから行われるため、感謝の温度が伝わりにくい。ほどよい中間には、借りた側が相手の生活を思い浮かべる時間が挟まる。食堂の鍋を借りた人が、洗ってから二日後の昼に届けるのは、鍋を乾かす時間も込みで、相手の台所の都合を想像した痕跡である。\n⟪借りた物を返す時刻の選び方そのものが、ことばにならない感謝の量を相手へ運ぶ調整装置である⟫。だから、返却に一言を添えるのは、遅れてしまった時間を少し埋め合わせする意味を持つ。逆に言えば、何も添えずに日数だけを置いて返すのにも、盆と正月をまたいで貸借を持ち越すのにも、それぞれ暗黙の作法がある。返すとは、借りた関係を閉じる行為ではなく、感謝という通貨の為替を、その都度やり直す仕事である。',
