      '年賀状の発行枚数は二十年で半分近くに落ちた。この減少をもって、人が互いの無事を確かめ合う習慣が滅んだと結論するのは早計だ。一月一日の朝に画面を開けば、かつて郵便受けに届いたはずの挨拶が、メッセージアプリのスタンプとして、何百という連絡先に一斉に流れている。手間と費用が下がった分、一行の言葉は軽くなった。だが、「今年もよろしく」という働きかけの構造そのものは、ほとんど変わっていない。\n年賀状の本質を、宛名を書く手間に置く見方がある。確かに手書きの筆致は温かみを運ぶ。しかし指摘すべきは、手間が減っても確認の回数が減っていないという事実だ。挨拶状の需要の正体は、文房具ではなく、一年に一度、続柄を更新し、絶交していないことを示す機会である。⟪減ったのは、つながりを確かめる需要のほうではなく、それを長年担ってきた紙という形式のほうである⟫。\n形式は再び移るだろう。印刷の年賀状からスタンプへ移った流れは、次に音声や動画の挨拶を含むかもしれない。ただし、古い形式が完全には死なない点に注意したい。手間のかかる挨拶ほど、受け取る側は自分を特別視されたという感覚を持ちやすい。だからこそ、安い形式が大量の軽いつながりを覆う一方で、大切な相手へは紙が残る。需要が消えない限り、替わるのは形式のほうだけで、確認の儀式は残り続ける。',
