    passage:
      '忘れ物の上位に傘が並ぶのには理由がある。雨の日は突然必要になり、晴れれば役目が消える。必要と不要が一日のうちに入れ替わる物は、携帯の負担が重い。それでも昔の人は傘を丁寧に扱った。一本が家計に占める割合が大きく、壊れれば骨を組み替えてまで直す時代には、持ち歩く手間など些細な煩わしさでしかなかったからだ。\n転機は安価なビニール傘の普及である。数百円という価格は、失くす痛みをほとんど感じられない大きさまで縮めた。以後、傘は手入れして長く使う所有物から、必要な時に調達する消耗品へと性格を変えた。店頭に雨の日だけ並ぶのも都度新調する客が絶えないからであり、家庭の傘立てが五本、六本に増えるのも、どれを持ち出したか確かめられないまま買った二本目、三本目である。\nつまり、忘れるたびに傘を買う習慣は単なる怠惰ではない。持ち歩く負担と調達の手軽さが、ほぼ等しい力で釣り合う地点に落ち着いた均衡の表れなのであり、⟪人は記憶を使う労より、安い買い物で記憶を省く道を選んだ⟫のだ。値段が注意力の代わりを務める。もし一本が五千円であれば、出かける前の空模様の確認は誰もが欠かさない習慣になっていたはずだ。簡便さとは、心を配る労を買い替え可能にする技術でもある。',
