    passage:
      '膝を痛めた隣の老婦人は、買い物の送迎を申し出る近所の人に決まって断っている。無下に追い返すのではない。食品の宅配を契約して自活の体裁を整え、人手を要する場面を極力作らないようにするのだ。本人に言わせれば、動けない体で人を待つ心苦しさのほうが、荷物の重さより重いという。だが、手を貸そうとした側の落胆は、目に見えないところで積もっていく。\n世間では遠慮は美徳とされる。では、好意を丁重に退けることは、なぜ問題を孕むのか。⟪遠慮は相手への配慮に見えて、実は関係から「頼る」選択肢を取り除く行為である⟫からだ。人は頼られることで初めて、その関係の中に自分の居場所を確認できる。世話を申し出ては断われ続けた人は、やがて声をかけなくなり、そこに付き合いは残らない。\nとはいえ、申し出をすべて受け入れるのも困難である。頼まれごとは喜びであると同時に、時間と体力を取る労働であり、引き受ける側が無理を重ねれば、関係は今度は負担の側から壊れていく。だからこそ、手伝いは断り方と頼み方の両方に工夫が要る。普段は要らないが、雪の日の外出だけは車を借りたい、と用途を絞って伝える。頼ることと負担をかけないことの間にある細い帯の上で、長く続く付き合いは保たれるのだ。',
