      '宛名も署名のない手紙が、冷蔵庫の扉に磁石で留められている。「夕飯は七時」「湯沸かし済」といった数行には、日付も敬称もない。この粗略さは手抜きではない。誰に読まれるかが分かっていて、書かれた事情を相手が即座に思い当てられると書き手が確信しているからこそ、説明の大半を省略できるのだ。\n手紙というと、距離のある相手に形式を整えて送る文を思い浮かべがちだが、家庭内のメモは逆に位置する。共有している背景が多いほど、文は短くて済む。⟪一言メモの短さは、家族が共有している文脈の厚さを測る物差しである⟫。「湯沸かし済」の五文字には、湯の用途、相手の予定、この家の流儀までが折り込まれている。書き手は伝えたい事柄の大半を紙の外に置き、読み手はそれを文脈から補って読む。\nもっとも、この省略の技術には危うさが伴う。共有される文脈を当てにした書き方は、その土台が途切れた瞬間に意味を失う。長年連れ添った片方を亡くした後、冷蔵庫のメモを前に書き手の意図を辿るように、短い文は文脈という名の地盤の上にのみ建っている。紙一枚の連絡が示すのは、家族の距離の近さだ。そしてその近さは、共有の継続と引き換えで保たれる、固定しない地盤の上にある。',
