    passage:
      '「平均年収」「平均的な世帯」といった言葉が、報道と政策の言葉づかいに定着して久しい。役所の資料も家庭向けの生活情報も、あたかも標準的な一軒が実在するかのように、平均値を中心に語る。だが平均という一つの数値は、その背後にある分布の形をまったく語らない。平均とは、多数者の中央に立つ実在の誰かではなく、足して割っただけの、計算上の点にすぎない。\n仕組みは単純な例で示せる。年収三百万円の人が九人と、年収二千七百万円の人が一人いたとしよう。平均は五百四十万円になるが、人数を二等分する真ん中の値、中央値は三百万円のままだ。五百四十万円という平均だけ聞けば、その集団はまずまず豊かに見える。しかし真ん中にいる人の懐は三百万円のままであり、数値に嘘はなくても、何を代表させるかで受け取る印象はまるで変わる。「平均五百四十万円」という発表は、九割の人の実収入を大きく上回る。少数の高額層が数値を上へ引っ張るかぎり、平均は多数者の姿から最も遠い場所へ置かれる。平均と中央値の乖離が広いほど、このねじれは深くなる。\nこのねじれは、政策の設計を静かに歪める。「平均的世帯」を想定して組み立てられた補助の基準は、分布の両端にいる人々、たとえば単身の高齢者や育児の負担の重い大きな世帯に届きにくい。平均に合わせた施策は、いざ運用してみれば多数者の実態にすら合わない。統計の読み方はそのまま政策の視線になり、助けを必要とする人々を見えなくするのである。\nもっとも、平均そのものが無用だと言いたいのではない。部品の寸法の管理のように、分布が釣り鐘型に収まる分野では、平均は依然として強力な要約である。問題は、歪んだ分布にまで平均を無自覚に適用する慣習のほうだ。⟪平均は山の頂の高さは教えてくれるが、山がどちらの斜面へ傾いているかは教えてくれない⟫。傾きを見るには、中央値や四分位といった、別の道具が要る。\n全体の姿を一つの数値に圧縮するその瞬間に、何が切り捨てられたのかを自覚すること。平均と中央値を並べて読み、分布の両端に誰がいるのかを問い直すこと。統計を扱う者の作法は、突き詰めればこの二つに尽きる。それを怠るとき、数字は実態の描写ではなく、都合のよい物語のための小道具へと変わる。',
