      '新しい薬が「有効」と報じられるとき、人々の期待は往々にして実力以上に膨らむ。臨床試験で効果が認められた薬は、その薬を手にする個人の病気にも必ず利く、と聞こえるからだ。だが統計の示す効果は、集団の平均的な差であって、目の前の一人の運命への保証ではない。薬はその人の中で利くか利かないかのどちらかであり、治療の判断は、いつだって不確実さのただ中で下される。\n仕組みから言えば、無作為化比較試験とは、薬を飲む群れと飲まない群れを偶然だけに委ねて分け、両者の結果の差を測る装置である。差が確かなら薬の効果の証拠になる。ただし、それが語るのは平均像の差であって、平均的な患者など現実にはどこにもいない。年齢と併用薬、腎臓の働き、一人暮らしの食事の事情。ガイドラインはそうした違いを平均へ切り整えた道標であり、例外の前では必ず沈黙する。医師の裁量が要請されるのは、道標が語らない場所である。\n数字の示し方も、判断を静かに傾ける。死亡率を二割下げると聞けば治療は魅力的に響くが、それが相対的な割合で、絶対的なリスクの低下は一％に満たないかもしれない。同じ事実が、翻訳の仕方ひとつで重さを変える。患者がどの治療を選ぶかは、数字そのものではなく、数字の運んでくる印象を通して決まるのである。\nもっとも、統計への依存を恣意からの解放として讃える向きには一理ある。根拠のない自信に支えられた治療は、実際に繰り返されてきたのだから。だが、平均をそのまま個人へ当てはめる機械化もまた誤りである。⟪統計が語るのは、よく似た人々の平均の姿であって、診察台に坐るこの一人のことを、何も保証してはいない⟫。数の威信が、個の判断の代役を務められるわけではない。\nだから判断は、共有の作業として行われるほかない。医師は数を患者の言葉へ翻訳し、患者は自分が何を重く見るのか、副作用の回避か、延命の見込みかを持ち寄る。二つの不確実さを重ね合わせて、共に決める。医学の不確実さは、研究の蓄積でいずれ払拭すべきノイズではない。治療の判断の形そのものを決める条件として、引き受けるべきものだ。',
