      'レジの前で小銭を数える手が、めっきり減った。カードをかざし、端末に顔を向ける。使う側にとって決済の形は多様になったが、ふと問いたくなるのは、硬貨の合金や紙幣の紙切れが、なぜパンと交換できるのかである。素材としてはほとんど無価値な物体が受け取られるのは、貨幣の本体が物ではなく、価値を記す台帳と、それを信じる人々の合意だからである。\n歴史を遡れば、貨幣の座に就いたのは貝殻であり、塩であり、金属だった。それ自体では役に立たないものが貨幣になれるのは、皆が同じものを次の支払いに受け取ると信じるかぎりにおいてである。金属は偽造と秤量の手間という難点を抱え、紙幣は発行者の信用にすべてを委ねた。かつて紙幣が金と引き換える約束の券だった時代を経て、いまその支えは政府と中央銀行への信頼に置かれている。貨幣とは、台帳の正確さと、台帳を信じる共同の思い込みに支えられた記録にほかならない。\n電子マネーとデジタル決済は、この台帳の純化である。銀行間の振替が、すでに帳簿の数字の書き換えにすぎないように、キャッシュレスは媒体から物を降ろして、記録だけを残す。新しい貨幣の発明ではなく、台帳からの搬出である。ただし純化は、信頼の集中を伴う。決済事業者の設備が止まれば、街の支払いが一斉に止まる。分散していた信用が、少数の拠点へ寄せられたのだ。\nもっとも、中央の保証人を排そうとする動きも現れた。取引の記録を参加者が持ち回りで保つ分散型の台帳は、信頼の置き場を技術へ移す試みだった。だが暗号資産の価格の激動が示すように、保証人の不在は安定を意味しない。⟪貨幣の力は、それを支える物の頑丈さではなく、それを受け取ろうとする人々の輪の広さで決まる⟫。輪の外では、どんなに精巧な記録も、ただの数字の集合にすぎない。\nならば残る問いは、信用を誰が保証するのかである。政府と中央銀行による保証は、歴史のうえでは新しい発明であり、その信頼が揺らぐとき、人々の信頼は記録から物への逃避として現れる。デジタル時代に問われるのは、貨幣が何でできているかではない。台帳の正しさと公平を、誰が、どの手立てで担保するのかである。',
