      '空港の到着ロビーで、夜遅い空腹を満たそうと顔を上げると、どこの国に降り立っても似た看板が目に入る。こってりしたスープの麺、挟んで食べる肉料理、氷のよく効いた甘い飲み物。そして、その看板の多くは、旅の先で見覚えのある顔ぶれである。街へ足を伸ばしても、系列の店は同じ内装で同じ値段帯を並べ、旅の記憶が味の記憶として残りにくくなった。\nこの均質は、世界中の舌の好みが勝手に収斂した結果ではない。流通と保存を担う仕組みの論理が押し出した形である。遠くへ運ぶ食材には、腐らず、傷まず、形がそろうことが何より求められ、品種改良は味よりも日持ちを軸に進んできた。冷凍と低温輸送の網が張り巡らされるほど料理は産地から切り離され、工程は数値化され、どこの厨房でも再現できる手順に変わる。味のぶれは利益のぶれに直結するため、料理は個性を削って誤差をなくす方向へ歩む。チェーン展開はこの手順を店舗の数だけ複製し、同じ成功を同じ場所で何度でもくり返す。\nもっとも、産地の名を冠した食品が人気を集めているのは事実で、これを均質化への反乱と見たくなる。だが、観察を進めれば、有名産地の味が全国の売り場にずらりと並ぶ光景は、均質を運ぶのと同じ流通機構の上で成立している。地域の銘柄が遠くの消費者に選ばれるとき、地域性は看板として旅行するのであり、包装された「らしさ」もまた一つの規格品になりうる。産地偽装がニュースになるのは、裏返せば、正しい産地の表示がそれだけの値段を持つに至った証拠だ。\nでは、地域の食はどこで生き延びているのか。⟪地域の味が本当に生き残るのは、土産として遠くへ運ばれるときではなく、その土地の暮らしの中で繰り返し食べられるときである。⟫ 朝の食卓に、市場の片隅に、学校給食の献立に。売り物にならない日常の反復は、観光地の名物とは別の速度で受け継がれる。流通に乗らないぶん消えやすくはあるが、くり返されるぶん、流行にも吹かされにくい。目にしにくいぶん、語られにくいだけでもある。\n均質化を嘆く言説だけでは、棚の並べ替え以上の何ものも守れない。保つべき対象は売り場の商品ではなく、暮らしのくり返しそのものだ。食文化を語るなら、遠くへ売る味と、そこで食べる味とを分けて考えるところから始めるべきである。',
