    passage:
      '「履歴書は大学名で九割が決まる」と言い切る人事担当者がいる。誇張に聞こえるが、応募者千人の能力をひとりずつ面接で確かめることは不可能に近い以上、大学という目印で一次のふるいにかける運用には、それなりの合理性が潜んでいる。厄介なのは、その目印が何を示すのかが、企業にも当人にも曖昧になってきたことだ。\n経済学には、学歴を能力の証明ではなく能力の合図と見る考え方がある。大学が人を賢くするから企業が学歴を買うのではなく、もともと処理の速い人が試験や単位の山を抜けてきた事実そのものが情報として売られる、という発想だ。この見方に立てば、学位の中身より大学の看板が重視されるのも不思議ではない。看板は遠くから読めるが、能力は面接室まで運ばないと見えないからである。\nところが高等教育が大衆化すると、合図は薄まる。持っている人が多すぎる信号は、誰のことも語らなくなる。そこで人々が選ぶのは、信号を捨てることではなく、いっそう強い信号を追うことだ。名門大学の次に大学院、大学院の次に資格の枚数へと、証明の競争は内側へ燃え上がる。個々の選択はそのつど合理的でも、集めれば社会全体で誰も得をしない軍拡競争が成立する。受験戦争が形を変えて続くのは、この構造のせいである。\nいっそう扱いにくいのは誤発報だ。入学試験が得意とするのは、限られた時間で与えられた問題を解く力であり、職場が求めるのは数年単位で他者と調整しながら仕事を仕上げる力だ。両者は無関係ではないが、重なりは部分的にすぎない。それでも企業が信号に頼り続けるのは、別の測り方がないからではなく、別の測り方には面接官の訓練や試用期間の確保といった費用がかかるからである。誤発報は誰かの無知の産物というより、確認の手間を安売りしたツケとして回ってくる。\nもっとも、だからといって選抜をやめてしまえば、採用の失敗は訓練の失敗という姿で現場へ戻ってくるだけだ。問われるべきは信号の正確さではなく、誤った採用を見抜く手間に社会がいくら払う覚悟をしているかである。経歴を細かく可視化し、実技や試用で選ぶ仕組みを整えることは、⟪ふるいを粗くすることではなく、学歴以外の目にもふるいを開くことにほかならない⟫。\n学歴は実力そのものではなく、それを確かめる手間の代金だ。合図の質を嘆く時代は終わり、手間の支払い方を設計する時代に入った、と私は考える。',
