    passage:
      '就職面接で年収の質問を差し控え、「御社で何が実現できるか」を語る学生が増えた、という話を旧い世代は半分感心し、半分訝る。生きるための仕事、という当たり前の並び順が、いつから逆さになり始めたのか。口先の新しさだと笑うのは容易いが、語彙の変化は、働くことの置かれた位置の変化に決して遅れない。答えを得るには、働くことの意味が時代ごとに置き換えられてきた足跡を辿るしかない。\n不作と飢饉が身近だった時代、労働は字義どおりの生計の手段であり、誇りはあっても「やりがい」を語る余裕は薄かった。産業化は職を一生分まとめて雇い入れる形式を生み、終身雇用の下で人は職業への忠誠と企業への帰属とを重ね合わせた。会社は生活の時間を管理し、住居を貸し、退職後の年金まで面倒を見る。労働の意味は「生計の手段」から「生涯の身分」へと持ち上がったのである。\nやがて成長の限界と技術の激変が、身分という厚い約束を解体し始める。同時に、働く場所と暮らす場所の境界が揺らぎ、職業を選ぶことは「どの会社に属するか」から「どんな人生を生きるか」の選択へと語り直された。仕事に自己実現を見出すことが美德とされ、転職は裏切りではなく成長の記録方式と見なされるようになった。\nだが、この新しい意味づけには落とし穴が開いている。⟪働きがいという言葉は、報いを用意する責任を企業から労働者自身の肩へとこっそり移した札である⟫。仕事が充実の源でなければならないと規定された瞬間、充実を実感できない人は、搾取の構造ではなく自分の能力と志の不足に理由を求め始める。やりがい搾取という言葉が生まれたのは偶然ではない。意味を求める自由は、意味を見出せない者への責任の転嫁と表裏なのである。\nもちろん、生計の手段という旧来の並び順への回帰を提唱したいのではない。賃金の公平も、生活を仕事から守ることも、依然として重要だ。問いたいのは、働く意味を一つの物語に押し込める態度である。働くことは明日の米を稼ぐことでもあり、同僚との関わりでもあり、時には自己実現でもある。意味の複数化を許すこと——それが、仕事への過剰な期待から人を解放する最短の道だろう。',
