      '共働きの家で家事が回らない原因は、怠けではなく、その都度決める手間にある。今日の弁当は誰が、洗濯物は誰が——毎回相談していたら、相談自体が仕事になる。だから我が家では、役割を一度固定した。朝食と弁当は私、夕食と洗濯は妻、掃除は機械と曜日で回す。担当が決まっていると、やり残しの責任が曖昧にならず、先方の手際も上達する。繰り返しは腕を磨き、腕は時間を短くする。分業の効用は、産業の歴史が証明している。むしろ曖昧な協力のほうが、二重の手間と責任の擦り合いを生む。同じ担当を重ねるうちに、各自の得意の型が育っていく。家事は限られた時間の中の生産活動である以上、割り当ては固定し、見直しは年に一度で足りる。',
