    passage:
      '病棟の申し送りでも、工事現場の打ち合わせでも、新人が最初につまずくのは内容ではなく、ことばの密度である。略語と外来語の嵐のなかで、意味を尋ねること自体が野暮という空気が出来あがっている場面は、どの専門職の世界にもある。私はこの専門用語を、廃止すべき悪ではなく、二つの顔を持つ道具として扱うべきだと考えている。\n第一の顔は、思考の省略装置としての顔だ。心不全による体液のうっ滞と一言で呼べる状態を、毎回、説明なしの平易な語にほどいていたら、診断方針を話し合う時間は残らない。用語は熟練者どうしのあいだで、長い推論を一語に圧縮する。この圧縮があるからこそ、議論は未知の部分へ進んでゆける。圧縮がなければ、毎回の会話は初歩の説明だけで終わり、経験の差を生かしきれない。むしろ用語を排した説明は文章が冗長になり、要点をかえって濁すことも多い。\nしかし第二の顔を見て見ぬふりをするのは欺瞞である。用語は、それを知らない者に入場を拒む門番としても機能する。説明を求めた新人が「それくらい勉強して」と一蹴されるのは、知識の不足への指摘というより、仲間入りを拒む合図だ。顧客への説明で専門用語を並べる業者がいるのは、理解されないほうが契約の細部を追及されないからで、排除はしばしば利益として計算されている。用語の乱用には、無意識の作法である場合と、意図的な防壁である場合とがあるのだ。\nでは、すべての用語を平易な語に置き換えればよいか。私の答えは否である。置き換えは、推論を一語に縮めるという圧縮の働きを失わせ、専門家どうしの思考をかえって遅くする。必要なのは用語の廃止ではなく、翻訳する義務を職務の一部として引き受けることだ。用語を使う者は、その意味の説明までをセットで提供する。その手間は負担ではなく、職業の熟練の一部だと考える。一語目を尋ねた新人を歓迎する職場は、実は圧縮の便をいちばんうまく使っている。用語を知っていることを入場の資格にするのではなく、用語を翻訳できることを勤めにする。この基準をひっくり返すとき、専門用語は初めて門番をやめ、思考の道具へともどる。',
