    source: '本站原创模拟（非真题）',
    passage:
      '上達している人の練習は、外から見ると妙にぎこちない。曲を最後まで通すのではなく、失敗の直前の小節だけを何度も止めて弾く。打撃練習でも、打てる球を打つのではなく、あえて苦手な球種を連投させる。彼らは何をしているのか。私はこれを、失敗の収集と呼びたい。練習とは、上手くいく反復ではなく、意図的に作った失敗をすみやかに回収する活動である。\n回収が働くのは、失敗から学びまでの距離が短いときだ。打ち損じの原因は、打球が飛んだ直後なら本人にも分かる。一週間後に指摘されても、そのときの身体の感覚はもう呼び起こせない。だから練習を設計するとき、最初に決めるべきは内容ではなく、結果が分かるまでの時間である。棋士が対局の直後に棋譜を並べるのは、記憶が新しいうちに誤りを言葉にするためであり、操縦訓練でシミュレーターが即時に採点するのも同じ理屈だ。採点までの時間を先に決めれば、練習の中身は自然と絞られてゆく。\n厄介なのは、「うまくいく練習」のほうが心地よく、続きやすいことだ。弾ける部分を繰り返す練習は気分がよいし、得意な球を打つ練習は自信になる。成功の反復は、たしかに練習した手応えをくれる。だが成功は、すでに持っている技の見本市にすぎず、新しい失敗を一つも集めない。ここで、失敗だらけの練習は自信を壊すのではないか、という反論が予想される。もっともな心配だが、自信を壊すのは回収されないまま放置された失敗であって、失敗そのものではない。拾い上げ、解析し、次の課題へ繰り込まれた失敗は、むしろ手応えになる。怖いのは失敗ではなく、無駄死にに見える失敗のほうだ。\nだから練習を設計するとき、私は成功率の高さをまず疑って見ることにしている。八割以上が上手くいく練習は、体に染みこんだ技の確認であって、学びの現場ではない。うまくいかなかった箇所に印をつける作業こそ、実は練習の中心である。今日の練習で新しい失敗をいくつ集めたか。その数を数え、一つひとつに短い説明を書かせ、次の練習の課題へ繰り込む。練習の質とは、うまさの反復量ではなく、失敗の回収率のことである。',
