    passage:
      '朝いちばんに工場に入ると、自分の担当の機械の前で、まず十分、ただ音を聴く。若い頃は「遊んでいる」と思ったこの時間の意味を、動力係の老技師は筆者にこう説明した。今日の機械の声を、昨日までの声と比べるのだと。機械は故障の前日から音を変える。外観は同じでも内側は毎日違う。この聴き比べこそ、この工場が四十年止まらなかった理由の一端だった、と。\nこのような手入れの時間は、効率の基準が職場に入ると、いちばん早く削られる。時間あたりの産出量で測れば、回転する機械の横で立って聴く人は「動いていない」。休み時間に器具の調子を確かめる看護師、閉店後に店内の空気を整える店主、書架の隅の乱れを直す司書も同じで、いずれも標準的な仕事の単位に乗らず、評価表の上では空白になる。\nさらに厄介なのは、習熟が静けさとして現れることだ。上手い人は危なげなく片付けるので、その作業には苦労が写らない。素人が四苦八苦する場面を淡々と終わらせる姿は、見る者に「簡単な仕事」の錯覚を与える。速さが成果と取り違えられたとき、熟練は報われない。劣る人ほど頑張りが見え、頑張りが見える人ほど評価されるという倒錯が、現場では静かに進行する。\nもっとも、効率の基準が一切ない職場がよいわけではない。基準の導入は、実態の見えなかった残業を暴き、恣意的な人事を防ぐ盾にもなった。数値にすることで初めて守られる労働があるのは事実だ。だが、基準が写せる範囲には限りがある。⟪速さを基準に据えたとたん、仕事の質は、速さに引き写せる部分だけになってしまう⟫。聴く三十分は、基準の言う「仕事」からは消える。\n消えた部分は、故障して初めて姿を現す。止まった工場を動かす費用、信頼を失う患者、戻らなくなった客。それらは「修理の費用」としては計上されても、「見えない手入れの価値」としては計上されない。だから私は、遅い仕事を遅いままで認める評価の枠を持つことを主張したい。速さのものさしは便利な道具ではあるが、それが職場に入る前にあった質を、ことばと信頼で写し取る視線を、私たちは手放してはならない。',
