    passage:
      '引き手の少なくなった夏祭りの山車を、ある町会は三年前に電動の牽引車に替えた。「本物ではない」という抗議の声は大きかったが、祭りは今年も商店街を回り、沿道は見物客で埋まった。替えなかった隣町の山車は、小屋の中で勝手に白木の色を深めている。形だけは完全に残ったまま、動かない引き手とともに眠っている。どちらが伝統を守っているのか、答えは単純ではない。\n形を固定する発想は、変化を「劣化」と呼ぶ。装束の縫い方も、囃子の音取りも、一度写し取った型から動くことを許さず、守る者の仕事は復元の精度だけになる。だが形を凍結した瞬間、その営みは生活の中の行事から、過去の再現という催しに変わる。演じる側は見る人のための役者になり、祭りは村の暦を離れて、ガラスケースの中の標本として生きることになる。\n一方、今日「昔ながら」と呼ばれるものを遡れば、そこに無変化の連続はない。着物の意匠は時代ごとの技術と流行で書き換えられ、歌舞伎の型も江戸期に何度も革新を積み重ねた。食の世界では、いまや定番とされる郷土の味の一部が、戦後の食材流通の中で固まったと語られる。伝統は、生き延びるために何度も作り直されてきた歴史そのものだ。\nとはいえ、形を守ることに価値がないと言うつもりはない。変わらない形は人に所属と安心を与え、勝手な改変が粗雑化を招く危険も実在する。勝手に変える者から見れば、守る側こそが権力に見えることもある。だが「変えない」という決定自体、現代に生きる誰かの判断である以上、無変化は神話でしかない。守ると言って形を固定する側にも、また選択と省略が働いている。ならば問われるのは、変化を禁じるか、生き延びるために手を入れるか、である。\nだから私は、守るとは作り直すことだと考えたい。次の環境で役に立ち続けられるよう、使う人の体に合わせて手を入れ、その改変を前の形と併せて語り継ぐこと。使い手が絶えて初めて、伝統は標本に変わる。白木のまま小屋で眠る山車よりも、モーターを引いても沿道に人を集める山車のほうが、伝統に近い。少なくとも、まだ生きているという点では。',
