    source: '本站原创模拟（非真题）',
    passage:
      'ご近所づきあいが希薄になったと嘆く声には、決まって昭和の路地の情景が添えられる。勝手に上がりこんでくる隣人、回し読みの広報、子どもを丸ごと預かる昼下がり。あの濃さこそ共同体の本来の姿で、いまの軽い付き合いはその劣化だとする語りである。私はこの神話に与しない。共同体は濃い絆から始まるのではない。最低限の関心の網から始まるのだ。\n密な付き合いには、維持の費用がかかる。役員を担ぎ、行事を回し、細部のしきたりを調整し続ける労力は、当事者にしか見えない重さで積み上がる。この初期投資を前に、多くの人は付き合いそのものから降りる。さらに濃さには影がある。参加できない者はよそ者として括られ、生活の内側まで仲間の目が届く。密な絆は支えの網であると同時に、監視の網でもあったのだ。降り残った者に負担が集中するため、濃い付き合いの世界では、重さが特定の人へ積もり続ける。\nいっぽう、軽い繋がりは安価で、それでいて働く。ゴミ捨て場で交わす一言、散歩の途中の会釈、自治会の回覧板の一枚。この程度の接点は、手間が小さいぶん、忙しい時期にも切れない。しかも顔見知りの網は、閉じた小集団よりも遠くまで情報を運ぶ。改装する店の噂も、ほどける手すりの話も、濃い友情より弱い接点のほうが早く届けてくる。交流の手間を削った結果、面だけは広く保たれる。これが軽い繋がりの実力である。\nもっとも、重い支えは軽さだけでは担えない、という反論は正しい。病気の見舞いも、災害の夜の避難も、深く関わる覚悟を要する。ただし考えたいのは順番だ。顔も名前も知らない隣人に、見舞いを頼める人間はいない。それに踏み出す一歩が、いちばん高いのだ。重い支えは、軽い網の上でしか届かない。軽い繋がりは深い関係の代替物ではなく、あらゆる支え合いの入口である。入口のない場所に、突如として濃い付き合いだけが発芽することはない。\nだから設計で問うべきだ。名前と顔を結ぶ機会を最初に用意する。参加の義務のない集まりを、定例で安価に開く。声をかけた側が断られても次がある作法を、会のほうが守る。負担の少ない接点を点々と張り、最低限の関心の網を保つ。それが、軽い繋がりを弁護する私の立場である。',
