    passage:
      '重大な事故のあとだけで報告の件数が跳ね上がる職場を、私は信用しない。事故直後の報告ラッシュは、よく安全意識の高まりの証拠として讃えられる。だが同じ現場で、半年前には何も提出されていなかった。意識が突然変わるはずがない。変わるのは、報告を出すことへの怖さのほうで、その怖さは日々少しずつ積み重なって、提出という行為そのものを止めてしまう。報告が集まらないのは、報告する人間の性格の問題ではない。受け取る側の設計の問題だと私は見ている。\n仕組みを分解すれば、一つの混同が見える。失敗の報告は、再発防止のための情報として集められる。ところが同じ文書が、人事評価の材料としても閲覧されている。提出した瞬間、その記録は直すための材料と、問うための材料の両方になる。報告者はこの二重の行き先を知っている。だから筆を引く。情報の入口と罰の入口が同じ窓口なら、窓口に近づく者が減るのは当然だ。最終的に報告として届くのは、外部に発覚した失敗だけで、それでは直すべき失敗の全体像は永遠に掴めない。\nでは、どう下げるか。報告のフォームから個人名の欄を最初から外す。再発防止を議論する検討会は、人事の席とは別のテーブルに置く。報告の中身が処分の根拠に流れないと、規則の文言で明示する。提出は選択式を主にして五分で終わる長さにし、出された報告がどの改善につながったかを、提出した本人へ速やかに返す。対応の速さが見えると、次の報告の動機になる。報告は、効いていないと分かった途端に止まる行為だからだ。\n罰しない制度は、ずさんな者を野放しにするのではないか、という反論には筋がある。しかし私は、責任を問うことの廃止を提案しているのではない。事故の調査そのものは従来どおり行い、問うべき線路は別に敷けばよい。むしろ罰の入口に情報を置くかぎり、調査は最初から不完全になる。見つかる失敗しか調査にかけられないからだ。直すための情報と、問うための情報を同じ容器に放り込むほうが、よほどずさんな設計である。\n⟪報告される失敗の量を決めるのは、失敗の多さではなく、報告した者が次にどう扱われるかである⟫。この一文を規則の第一項に置くだけで、現場の筆は止まらなくなる。ハードルを下げるとは、現場の声を大きく張り上げさせることではなく、戸口そのものを低くすることだ。失敗を隠さない職場とは、勇敢な人間が集まった職場ではない。言うまでの怖さを、設計が削り取ってくれた職場のことだ。',
