    passage:
      '商店街の花壇が雑草に覆われ、川沿いの桜並木の落ち葉が誰にも集められず、団地の共用廊下の電球が三か月も切れたままになっている。どれも大事件ではないが、暮らしの質を静かに下げていく現象である。三つに共通するのは、手入れをしていた人がいなくなったことだ。転居、高齢化、仕事の忙しさ。担い手が一人減るだけで、共有物の手入れはたちまち止まる。\n共有の場は、税金だけで支えられているわけではない。清掃当番の三十秒、帰りがけの草むしり、回覧板を回す足、祭りの段取り。そうした誰かの「ついで」の手間が積み重なって、共有の質は保たれてきた。ところが利便の選択は、この手間を一つずつ買い取っていく。宅配を頼めば買い物の外出が減り、便利な街へ移れば自治会から離れ、請負サービスに任せれば当番の名簿から名前が消える。選ぶ本人に落ち度はない。便利なほうを選ぶのは当然だからだ。問題は、その当然の選択が積み重なったとき、手間の担い手だけが静かに減っていく構造である。残った者への負担が増え、ついに輪が崩れ、最後は有料の業務委託で元に戻す。費用は誰が払うのか。使う全員である。\n金で解決すればよい、という反論には一理ある。専門業者の仕事は丁寧だし、無償の当番を世代に押しつける文化をそのまま肯定する気にもならない。確かにそのとおりで、委託そのものを否定するつもりはない。だが、手間には金では買いにくいものが付随している。掃く人はその場所の異変に最初に気づく。毎日通るからこそ、段差、滲み、壊れかけの手すりを自分の目で記録している。外注された作業は、指定された範囲だけを受け持つ。観察が消え、報告も消える。手間を担う人は、単に掃除しているのではない。その場の状態を知る数少ない観測者として、共有物を見張っているのである。\nだから私は、手間を「負担」と呼ぶ言葉遣いをやめたい。負担とは取り除くべきものだが、参加とは引き受けることでその場に関係に入ることだ。制度でできることは単純である。共有物のそばに、小さく、短く、誰にでもできる手間を配置し、それを引き受けた事実が目に見える形で残る設計にすることだ。十鉢のうち一鉢の水やり、月一度の電球交換。偉くも得にもならないが、住人はその場の質を自分の事として観測し続ける資格を取り戻す。便利さを買う自由はそのままに、その支払いが誰かの参加を消していたと気づくこと。それが、手間の見直しの出発点になると私は考える。',
