    passage:
      '講演のあとの質疑で、若い書き手が来場者から問い詰められていた。この作品は結局、何を言いたいのですか、と。筆者はしばらく黙り、書いた当時のことは、もう自分にも分かりません、と答えた。会場には不誠実だという空気が広いたが、私はこの答えに最大限の正直さを感じる。意味の最終的な管理者が筆者である、という通念は、書くという行為の実態と食い違っている。\n書かれたことばは、声の高さも表情も間も運べない。書き手の胸の中にあった意味のうち、紙面に定着したのはほんの一部で、残りは筆を置いた時点で蒸発する。読み手はその欠けを、自分の時代と経験で埋めるしかない。だから同じ古典が、ある時代には恋の物語として読まれ、別の時代には身分の物語として読まれてきた。変化しているのは読み手の側の文脈であって、活字は一字も動いていない。意図を手がかりに読むこと自体は悪くないが、意図はあくまで推測であり、推測を解釈の採点基準に据えると、読む行為は発掘作業にすり替わってしまう。\nもちろん、意図の軽視には危険が伴う。何でもありの解釈を許せば、批評は言葉遊びに堕する。本文の細部に即かない読み、都合のいい箇所だけを拾う読みは、読みではなく施工である。私が言いたいのは、意図を無視してよいという話ではない。意図を解釈の唯一の正解と見なす採点方式を手放そう、という話である。文献の知識と時代背景の把握は読みの土台としてむしろ厳格に求めるべきで、問題はその土台の上に何を建てるかの権利の所在だ。\n私はここで、解釈の権威は書き手から読み手へ移ると言いたい。⟪書かれた瞬間から、ことばは書き手の手を離れ、読み手の側へ引き取られる⟫引き取った読み手は、自分の解釈に責任を持つ義務を負う。これは自由の宣言ではなく、責任の請求書である。あの箇所はこう読める、と言う者は、本文のどこに立脚した読みなのかを示さなければならない。権威を受け取るとは、根拠の提示義務を引き受けるということだ。\n読書とは、過去の意図を掘り当てる作業ではなく、ことばを受け取って現在に建て直す営みである。読み手が解釈の名義人になった以上、その読みには署名が要る。根拠を示して読む者が、はじめてことばを自分のものにする。書かれたものは読み手のものとは、そういう責任の移転のことである。',
