    passage:
      '【市民水泳大会 参加者の募集について（7月1日）】\n市民プールを会場に、市民水泳大会を9月10日（日）に開催します。本大会は予選を行わない記録会形式で、各種目を1回泳いだタイムで順位を決めます。小学生から大人まで、幅広い年代のご参加をお待ちしています。\n＜種目と参加資格＞\n・50メートル自由形：中学生以上。\n・50メートル平泳ぎ：小学4年生以上。\n・25メートル背泳ぎ：小学生のみ。中学生と一般の方は出場できません。\n※学年は大会当日の9月10日時点で判断します。\n＜参加料と申込方法＞\n・参加料は1種目につき500円です。ただし、1人が申し込めるのは2種目までとします。\n・申込締切は8月25日（金）。この日までに窓口へ持参するか、郵送の場合は必着となるようお送りください。\n・申込書は市役所スポーツ課と市民プールの窓口にあります。\n＜当日の持ち物＞\n・水着・スイミングキャップ・ゴーグルは必須です。タオルや着替えもお忘れなく。\n・観覧は自由ですが、応援の際は指定の観覧エリアをお使いください。\n＜開催と中止の判断＞\n・会場が屋内のため雨天でも決行します。ただし施設に被害が出たなど、やむを得ない場合は中止となります。\n・中止の判断は、当日の午前7時に大会のホームページと参加者へのメールでお知らせします。電話による確認の受付けは行いません。\n・駐車場が混み合う見込みのため、乗り合わせてのお越しをお勧めします。\n＜問い合わせ先＞\n大会実行委員会事務局（平日 午前10時〜午後4時／電話 0XX-789-0123）',
