    passage:
      '【環境センター ごみ持ち込み受付けの変更について（4月15日）】\n環境センターに家庭のごみを直接お持ちいただく「持ち込み利用」について、4月24日（月）から受付けの内容を変更します。ごみの減量と適正処理を進めるための変更です。お出かけ前に、次の内容をご確認ください。\n＜受付けの日時＞\n・第2・第4土曜日の午前9時〜正午、午後1時〜4時。\n・平日の持ち込みは受け付けなくなりますので、ご注意ください。\n・受付けは終了時刻の30分前までとします。\n＜手数料＞\n・10キログラムまで200円。以降は10キログラムごとに100円を加算します。\n・お支払いは現金に限ります。クレジットカードや電子マネーは使えません。\n＜持ち込めるごみ・持ち込めないごみ＞\n・持ち込めるのは、家具・自転車・布団など、家庭から出た大型ごみです。\n・テレビ・冷蔵庫・洗濯機・エアコンなど、家電リサイクル法の対象品は持ち込めません。\n・店や会社などの事業活動で出たごみ（事業系ごみ）は、家庭のごみと一緒でも受け付けできません。\n・持ち込みの際は、入り口で車両のナンバーを確認させていただきます。\n＜事前申請について＞\n・一般の家庭でも、1回に持ち込む量が50キログラムを超える場合は、利用日の1週間前までに環境センター窓口で申請書を提出していただきます。\n・申請書は市のホームページからもダウンロードできます。\nご不明な点は、下記までお気軽にお問い合わせください。\n＜問い合わせ先＞\n環境センター業務課（平日 午前9時〜午後5時／電話 0XX-890-1234）',
