    passage:
      '【湾岸動物園 夜間開園「よるの動物園」のお知らせ（7月15日）】\n夏の夜、動物たちは涼をとりながら動き、昼間とは違う姿を見せてくれます。当園では例年好評の夜間開園を、8月5日（土）から8月27日（日）までの土曜・日曜に実施します。ふだんは午後5時に閉園しますが、実施日は次のとおり営業時間を延長します。\n＜実施日と時間＞\n・実施日は8月5・6・12・13・19・20・26・27日の土曜と日曜です。\n・入園の受付けは午後8時まで、閉園は午後10時です。午後5時までにご入園の方は、追加料金の支払いなしで、そのまま夜間開園もお楽しみいただけます。\n＜入園券について＞\n・午後5時以降にご入園の場合も、通常の入園券（大人500円・小人100円）や年間パスポートでご入園いただけます。夜間開園用の特別券はありません。\n＜ライトアップゾーンについて＞\n・園内東側の「夜の森ライトアップ」エリアは、入園券とは別に追加料200円（大人・小人同額）が必要です。受付けはゾーン入口で、お支払いは現金に限ります。\n＜雨天時の開催判断＞\n・小雨の日は実施しますが、気象警報（大雨・雷・暴風）が出ている間は中止します。\n・中止の判断は、当日の午後3時に当園のホームページでお知らせします。電話での個別のご確認には応じかねます。\n＜その他＞\n・園内のレストランは午後9時がラストオーダー、売店は午後9時30分まで営業します。\n・午後6時と午後8時に、ライオンやアザラシの給餌の時間を設けます。\n＜問い合わせ先＞\n湾岸動物園管理事務所（平日 午前9時〜午後5時／電話 0XX-555-6666）',
