    passage:
      '【区からのお知らせ 災害時帰宅困難者受け入れ施設について（8月30日 掲載）】\n大規模な地震などが起きて交通機関が止まると、多くの方が帰宅できなくなるおそれがあります。区内では、コンビニエンスストアやスーパーなどと協定を結び、歩いて帰る方のための一時的な滞在場所を確保しています。当区の受け入れ施設の内容は、次のとおりです。\n＜受け入れの対象と滞在＞\n・徒歩で帰宅される方が対象です。自家用車やタクシーで移動する予定の方は対象外です。\n・大きな地震の後は、むやみに移動を始めないことが原則とされています。発災から2日間（48時間）は、この施設で状況を確認しながら待機することをおすすめします。\n・滞在中は、1人あたり水1本（500ミリリットル）と非常食1食を無料でお渡しします。\n・毛布などの備蓄品は貸し出しです。帰宅の際にご返却ください。傘や電池など個人で使う品物の提供はできません。\n＜情報提供＞\n・施設内のモニターで、交通機関の運行状況や余震の情報、天気の見通しをお知らせします。英語・中国語・韓国語の案内もあります。\n＜家族への連絡手段＞\n・公衆電話や災害用伝言ダイヤル（171）を優先的にご利用ください。スマートフォンの充電も、1回20分まで無料でできます。\n＜注意＞\n・帰宅を開始する目安の時刻は、交通機関の再開の見込みが立った時点で、そのときの情報に従って判断してください。夜間の徒歩での帰宅はおすすめしません。\n・ペットの同伴はできません。\n＜問い合わせ先＞\n区役所防災課（平日 午前9時〜午後5時／電話 0XX-505-6060）',
