    passage:
      '【本町一丁目 まちなみ清掃の日のご案内（6月10日 掲載）】\n街をきれいに保ち続ける力は、大きな行事よりも、暮らしの中の小さな積み重ねから生まれます。本町一丁目自治会では、毎月、月の最初の日曜日の午前に、区域内の通りと公園の清掃を行っています。自治会への加入の有無を問わず、どなたでも自由にご参加いただけますので、ぜひお立ち寄りください。\n＜日時と集合場所＞\n・実施日：毎月第1日曜日 午前8時〜9時半。小雨のときは決行します。\n・集合は一丁目公園の東入口前です。9時に分担区域を告げて各班へ移動するため、遅れた方は北側商店街のアーケードで清掃中の班に合流してください。途中参加や早退も自由です。\n＜持ち物＞\n・軍手、帽子、飲み物は各自でお持ちください。ゴミ袋とトングは自治会が用意します。\n・軍手を忘れた方には、使い捨ての手袋を少数だけ貸し出します。確実に必要な方はご持参をおすすめします。\n＜雨天時の扱い＞\n・荒天が見込まれる場合は、翌週の同じ日曜日に順延します。決行か順延かの判断は、当日朝7時に自治会の回覧メールでお知らせします。\n・順延した回も雨で実施できなかったときは、その月の清掃は中止とし、翌月に持ち越します。\n＜参加登録＞\n・一般の方の事前申し込みは不要です。当日、集合場所の受付で名前を書いていただくだけで構いません。\n・自治会に加入している方は、人数の把握に使うため、参加・不参加を問わず、実施週の前の金曜日までに幹事へ連絡してください。\n＜問い合わせ先＞\n本町一丁目自治会事務所（火・木 午後1時〜5時／電話 0XX-777-0123）',
