    source: '本站原创模拟（非真题）',
    passage:
      '【たまてばこ 高齢者スマートフォン教室の受講者募集（10月2日 掲載）】\n「聞き返すのが気まずくて、結局分からないまま」——そう感じてきた方にこそ来ていただきたい教室です。講師は情報系の大学に在学する学生ボランティアが務め、同じ操作を何度尋ねても根気強くお答えします。分からないまま終わらせないことが、この教室の方針です。\n＜対象＞\n・市内にお住まいの65歳以上の方。教室で使うのは、ご本人名義のスマートフォンです。まだお持ちでない方は受講の対象になりませんが、機種の選び方については別途相談を受け付けます。\n＜コースと定員＞\n・入門コース：全4回。電源の入れ方から、電話をかける、文字を入力するまでを学びます。定員12名。\n・写真整理コース：全2回。スマホで撮った写真の見かた、整理のしかた、家族への送り方。定員12名。\n・個別相談：1回30分。困っている操作を学生に直接質問できます。1回につき3名。\n＜受講料＞\n・どのコースも無料です。教材費などもかかりません。\n＜申し込み＞\n・10月12日（木）午前9時から、地区社会福祉協議会の窓口で受け付けます。電話での申し込みはできません。先着順で、定員に達し次第締め切ります。\n・一度にお申し込みできるコースは、お一人につき1つだけです。終了後、空きがあれば別のコースも改めて申し込めます。\n＜教室での約束＞\n・操作の分からない部分は、その場で何度でも聞き直してください。同じ質問の繰り返しを遠慮する必要はありません。\n＜問い合わせ先＞\nたまてばこ運営事務局（平日 午前10時〜午後4時／電話 0XX-909-4567）',
