    passage:
      '【駅東口タクシー乗り場の仮移設について（11月20日 掲載）】\n夕方、通勤客と乗り場待ちの車が交差する駅東口の広場では、歩行者とタクシーの動線が重なり、接触の危険がこれまで何度も指摘されてきました。市と駅の管理者はこのたび、広場の改修工事を行うことにし、それに伴って東口タクシー乗り場を仮移設します。工事期間中は、下記の内容にご協力をお願いします。\n＜移設期間と場所＞\n・期間：12月1日〜来年3月31日。工事の進み具合により、前後する可能性があります。\n・仮乗り場は、東口ロータリー北側の仮設駐輪場の跡地です。エレベーター沿いの通路をまっすぐ進んだ先にあります。\n＜仮乗り場のご利用方法＞\n・西口の乗り場は変更なく、これまでどおりご利用いただけます。\n・仮乗り場は2本のレーンに分かれており、1番が在来線方面、2番が高速バスターミナル方面のお客様の受け付けです。\n・帰宅時間帯など混み合う時間は、係員が並ぶ位置を誘導し、列を後方へ延ばすことがあります。途中で列を飛ばさず、係員の指示に従ってください。\n＜注意事項＞\n・工事の間、東口の従来の乗り場からタクシーに乗ることはできません。乗る場所は必ず仮乗り場です。\n・目的地で降りる場所の変更はありません。これまで同様、駅周辺の交差点付近での降車が可能です。\n・迎えに来た自家用車など、タクシー以外の車の仮乗り場周辺での一時停車は固くお断りします。\n＜問い合わせ先＞\n市交通政策課（平日 午前9時〜午後6時／電話 0XX-222-8899）',
