      '【管路工事に伴う断水と給水のご案内（9月1日 掲載）】\n水は出て当たり前——そう感じるほど、断水は暮らしの根幹を揺さぶります。9月12日（火）午後1時から翌13日（水）午後5時まで、配水管の交換工事のため、市中部の中央1〜4丁目と旭町の全域で断水が予定されています。つきましては、下記のとおり給水を受け付けますので、必要な方はご利用ください。\n＜給水場所と時間＞\n・市役所中央駐車場：12日 午後2時〜午後8時。\n・旭町公民館駐車場：12日 午後2時〜午後8時、13日 午前6時〜午後3時。\n・どちらも蛇口をひねってくむ方式です。係員が列の整理を行います。\n＜持ち物と量＞\n・容器は必ず各自でご持参ください。ふたが閉まり、持ち運びやすい物が適しています。\n・くめる量は、お一人さま1回につき10リットルまでです。ペットや観葉植物の分もこの中に含まれます。\n＜高齢の方・体の不自由な方へ＞\n・ご自宅まで水を運ぶのが難しい要配慮者には、自治会を通じて宅配を行います。\n・宅配を希望する方は、地区の民生委員へ9月8日（金）までに連絡してください。当日の連絡では対応できません。\n・宅配の量は1世帯あたり20リットルです。\n＜給水車の要請＞\n・集会所の行事など、まとまった人数に給水が必要な場合は、水道局施設課へ電話で要請してください。手配の可否は、こちらで確認のうえお伝えします。\n・個人のお宅への給水車の手配はできません。\n＜問い合わせ先＞\n市水道局 施設課（断水期間中も終日受け付け／電話 0XX-505-1122）',
