      '【献血ルーム「みなと」の受付拡大のお知らせ（10月10日）】\n市中心部の献血ルーム「みなと」では、ご協力いただける方の利便性を高めるため、10月20日（火）から、平日の受け付けと閉室の時刻を、これまでの午後5時から午後7時に延長します。土曜・日曜・祝日は、午後4時までで変更ありません。\n\n＜献血の種類と受け付けの締め切り＞\n献血には、血液の成分を分けて採る成分献血と、一定量をそのまま採る全血献血があります。成分献血は採取に約90分かかりますが、全血献血の採取自体は10分ほどで終わります。受け付けの締め切りは、成分献血が閉室の1時間前まで、全血献血が30分前までです。初めての方は、受付で問診票のご記入をお願いします。\n\n＜当日のお願い＞\n献血の前日には、6時間以上の睡眠と十分な食事をとってお越しください。前日に深酒をされた方は、当日ご協力をお断りすることがあります。献血カードをお持ちの方はご持参ください。お持ちでなくてもご協力いただけますが、受け付けに時間がかかります。お車でお越しの際は、専用駐車場（30台）がご利用できます。\n\n＜次の献血までの間隔＞\n全血献血のあとは12週間、成分献血のあとは2週間、間隔をあけていただく必要があります。間隔は、前回の献血の日から数えます。間隔が足りない場合は、ご希望に添えないことがあります。\n\n＜問い合わせ＞\n献血ルーム「みなと」電話 0XXX-XX-9010（年中無休 午前9時〜午後8時）',
