    passage:
      '【第40回みなとたいまつ祭の見学のご案内（8月1日）】\nみなとたいまつ祭実行委員会では、9月第2土曜日の夕べに、みなと公園の特設広場でたいまつ祭を開催します。台風による中止が続いた昨年から1年を経て、多くの方からご要望のあった節目の回です。炎が港を照らす様子を、ぜひご覧ください。\n\n＜開催日時と中止の判断＞\n開催は9月第2土曜日の午後6時から午後9時までです。たいまつに火が入る点火式は午後6時半からです。当日の天気が心配な場合は、午後3時に開催の可否を決定し、公式サイトと駅前ビジョンでお知らせします。中止になった場合の振替開催はありません。\n\n＜観覧について＞\n観覧は自由席のみで、有料の指定席は設けません。開始の1時間前から、広場の縁での場所取りができます。座布団やレジャーシートの持ち込みは自由です。\n\n＜露店について＞\n会場の周りには、地元商店街が出す露店が約30軒並びます。焼きそばや魚のすり身揚げなど、港ならではの味を楽しめます。涼しくなる夕べには、温かい飲み物の露店も人気です。飲み歩きのゴミは、所定の回収箱へお願いします。\n\n＜交通について＞\n当日は会場周辺の道路で交通規制が行われ、車でのご来場はできません。臨時駐車場も当日は閉鎖されます。お越しの際は、最寄り駅から徒歩10分の道のりをお歩きください。自転車の方は、駅前の駐輪場をご利用ください。\n\n＜問い合わせ＞\nたいまつ祭実行委員会（市役所商工観光課内）電話 05XX-XX-2233',
