    passage:
      '【卒業証書の再発行について（4月1日）】\n市立みなと高等学校では、卒業証書を紛失または汚損された卒業生の方を対象に、下記のとおり再発行の受け付けを行っています。紛失や汚損の理由にかかわらず、手続きの内容は同じです。\n\n＜手続きの窓口と方法＞\n受け付けは、市役所本庁舎2階の学務課の窓口で行います。各支所では取り扱っていません。窓口の受け付け時間は、平日の午前8時30分から午後5時までです。窓口に来られない場合は、郵送での申請も可能で、その際は申請書と返信用切手を同封してください。\n\n＜必要な書類＞\n再発行申請書（ウェブサイトからも印刷できます）と、運転免許証やマイナンバーカードなどの本人確認書類が必要です。写真は不要です。書類に不備があった場合は、再提出をお願いすることがあります。\n\n＜交付までの日数＞\n窓口での申請は、その日のうちに交付します。郵送での申請は、書類が届いてから1週間ほどで、証書を郵送でお返しします。繁忙期にはお時間をいただくことがあります。\n\n＜代理人による申請＞\nご本人が窓口へ来られない事情がある場合は、本人の署名のある委任状があれば、家族や知人が代わりに手続きをできます。委任状の様式はウェブサイトから手に入ります。代理人の方も本人確認書類をお持ちください。\n\n＜手数料＞\n1通300円です。窓口では現金でお支払いください。郵送申請の場合は、現金ではなく定額小為替を同封します。\n\n＜問い合わせ＞\n学務課 電話 05XX-XX-8080',
