    passage:
      '【市民広場コンサートの開催基準について（5月20日）】\n市民広場で毎月最終日曜に開いている無料のコンサートでは、天候による中止の判断を、次の基準で行っています。入場の際に参加費500円をお願いしています。中止の連絡を受け取りたい方は、サイトの申し込みフォームから参加登録をしてください。参加登録の受け付けは、開催日の前日までです。\n\n＜中止を判断する時刻と基準＞\n中止かどうかは、開催日の前日である土曜の午後5時に判断します。判断には、気象台がその日の正午に発表した予報を使い、会場付近の風速が15メートル以上と予想される場合、または24時間の雨量が50ミリを超えると予想される場合に、中止とします。どちらか一方に当てはまれば中止です。\n\n＜中止のお知らせ方法＞\n中止が決まったときは、この催しの公式サイトと、参加登録をされた方へのメールでお知らせします。電話での個別のご連絡は行っていません。\n\n＜振替と参加費について＞\n中止となった回の振替開催は行いませんが、参加費の500円は、申請の必要なく全額をお返しします。返金の方法は、登録の際にお知らせした口座への振込みです。\n\n＜当日の朝の確認＞\n当日の午前7時に、公式サイトの「本日のお知らせ」欄と会場の掲示板で、開催の最終確認ができます。これは中止の判断をやり直すものではなく、判断はあくまで前日に行われます。\n\n＜問い合わせ＞\n市民広場コンサート事務局 電話 05XX-XX-4411',
