    id: 'sim-joho77', typeKey: 'joho', title: '模拟664 公衆無線LAN拡張', minutes: 4,
    source: '本站原创模拟（非真题）',
    passage:
      '【公共施設の公衆無線LAN拡張について（9月1日）】\n市では、9月1日から、公共施設で利用できる公衆無線LANの対象を拡大します。これまでは、市立図書館の閲覧室で、利用者証を提示した方に限ってご利用いただいていましたが、拡大後は、下記の3施設で利用者証なしで使えるようになります。\n\n＜対象の施設と範囲＞\n対象は、市立図書館、市民会館、駅前交流センターの3施設です。市立図書館では閲覧室を含むすべてのフロアで、市民会館と駅前交流センターでは、来館者が自由に過ごせるロビーだけでご利用いただけます。対象施設は今後も順次広げていく予定です。\n\n＜利用の条件＞\n利用は無料です。接続には1日ごとのパスワードが必要で、当日分のパスワードは、各施設の案内カウンターで発行します。前日以前に受け取ることや、ウェブサイトでの公開はありません。1人につき同時に接続できる端末は2台までで、家族で来館した場合も1人あたりで数えます。\n\n＜つながらないときは＞\n接続に困ったときは、まずお立ち寄りの施設の案内カウンターにご相談ください。カウンターでは、端末の設定までお手伝いできない場合があります。それでも解決しないときは、市役所情報政策課（電話 05XX-XX-7000）へお問い合わせください。\n\n＜ご利用にあたっての注意＞\n混雑した時間帯は速度が落ちることがあります。電源の使用は、各フロアの専用席に限りますので、ご協力をお願いします。長時間の席の占有は、ほかの方のご迷惑になります。',
