      '【市民スキー教室の参加者募集（11月10日）】\n市スポーツ振興課では、雪と親しみ健康づくりにつなげてもらおうと、初心者・初級者向けのスキー教室を開きます。基礎から丁寧に教えるので、初めての方も安心して参加できます。初心者を優先しますが、定員に余裕がある場合は経験者のお申し込みも受け付けます。\n\n＜実施日・対象＞\n実施日は1月17日・24日・31日の土曜日の計3回です。対象は市内在住の方で、定員は30名。申し込みが多数に上った場合は、スキー経験が1シーズン未満の方を優先して選考します。\n\n＜参加料・リフト券＞\n参加料は3回分で大人4,000円、中学生以下2,000円です。リフト券は含まれず、現地で各自が1日券（4,500円）を購入します。\n\n＜用具のレンタル＞\nスキー板やウェアは、現地のショップで借りられます。借りたい方は、12月20日までに、申し込みのときにお知らせください。当日その場での貸し出しは行っていません。\n\n＜バスの利用＞\n貸切バスを運行します。当日は6時50分までに市役所前に集合し、7時10分に出発します。往復のバス代は1,500円で、現地に直接集まる方は不要です。\n\n＜中止の場合の連絡＞\n荒天や雪不足で中止するときは、前日の17時までに市のウェブサイトと参加者へのメールでお知らせします。中止となった回については、参加料から1回分相当を返金します。返金の方法については、改めてご案内します。\n\n＜問い合わせ＞\n市スポーツ振興課（平日9時〜17時）電話 05XX-XX-7740',
